1	// free-guests-platform-walk.mjs — D-147 (plan/free-guests.md § 3.3), the
2	// platform form's field ON SCREEN, against pnpm dev. The HTTP side is
3	// free-guests-walk.mjs check 1; this is the browser side it left owed.
4	//
5	//   (cd packages/db && node --conditions=react-server --env-file=../../.env ../../plan/free-guests-platform-walk.mjs)
6	//
7	// A THROWAWAY super user and a THROWAWAY tenant with its DPA signed (villa's
8	// is unsigned, and the gate fires on the upsert: R-62), bookings switched on
9	// over HTTP; both removed at the end by the ids this run made (trap 26).
10	//   1. 1280: the tenant form's Applications tab draws "Children stay free up
11	//      to age" in Limits, empty, beside the hint; photographed.
12	//   2. typing 3 and Save config: the toast says saved, the record holds 3,
13	//      and a fresh page shows 3 in the field.
14	//   3. typing 18: the native control refuses it (max 17, D-142) and nothing
15	//      is sent; with the attribute removed, the server's refusal is the
16	//      toast, in the trigger's words, and the record still holds 3.
17	//   4. 375: the same field, photographed.
18	// Nothing reaches OpenAI.
19	
20	import { randomBytes } from 'node:crypto';
21	import { mkdirSync, writeFileSync } from 'node:fs';
22	import { dirname, join } from 'node:path';
23	import { fileURLToPath } from 'node:url';
24	import { supabase } from '../packages/db/dist/service.js';
25	import { openBrowser } from './ui-refresh-cdp.mjs';
26	
27	const BASE = process.argv[2] ?? 'http://localhost:3000';
28	const OUT = join(dirname(fileURLToPath(import.meta.url)), 'free-guests');
29	mkdirSync(OUT, { recursive: true });
30	const sleep = (ms) => new Promise((r) => setTimeout(r, ms));
31	
32	let failures = 0;
33	const check = (ok, what, detail = '') => {
34	  failures += ok ? 0 : 1;
35	  console.log(`${ok ? 'PASS' : 'FAIL'}  ${what}${detail ? `  — ${detail}` : ''}`);
36	};
37	async function call(method, path, { cookie, json } = {}) {
38	  const headers = {};
39	  if (cookie) headers.Cookie = cookie;
40	  let body;
41	  if (json !== undefined) {
42	    headers['Content-Type'] = 'application/json';
43	    body = JSON.stringify(json);
44	  }
45	  const response = await fetch(`${BASE}${path}`, { method, headers, body });
46	  const text = await response.text();
47	  let data = text;
48	  try {
49	    data = JSON.parse(text);
50	  } catch {
51	    // not JSON
52	  }
53	  const setCookie = (response.headers.getSetCookie?.() ?? []).map((c) => c.split(';')[0]);
54	  return { status: response.status, data, cookie: setCookie.find((c) => c.startsWith('rag_')) };
55	}
56	const err = (r) => (typeof r.data === 'object' && r.data ? r.data.error : String(r.data).slice(0, 80));
57	const storedAge = async (tenantId) => {
58	  const { data } = await supabase.from('tenant_applications').select('config').eq('tenant_id', tenantId).eq('application_key', 'bookings').single();
59	  return data?.config?.free_up_to_age;
60	};
61	
62	const stamp = Date.now();
63	const slug = `free-platform-${randomBytes(3).toString('hex')}`;
64	const NAME = `Free Field Resort ${randomBytes(2).toString('hex')}`;
65	let userId = null;
66	let tenantId = null;
67	let browser = null;
68	try {
69	  const email = `free-platform-${stamp}@example.com`;
70	  const password = randomBytes(18).toString('base64url');
71	  const { data: user, error: userError } = await supabase.auth.admin.createUser({ email, password, email_confirm: true });
72	  if (userError) throw new Error(`create user: ${userError.message}`);
73	  userId = user.user.id;
74	  const { error: superError } = await supabase.from('platform_admins').insert({ user_id: userId });
75	  if (superError) throw new Error(`platform_admins: ${superError.message}`);
76	  const login = await call('POST', '/api/platform/session', { json: { email, password } });
77	  if (login.status !== 200 || !login.cookie) throw new Error(`login ${login.status}: ${err(login)}`);
78	  const cookie = login.cookie;
79	  const created = await call('POST', '/api/platform/tenants', { cookie, json: { slug, businessName: NAME, assistantName: 'Fay' } });
80	  tenantId = created.data?.id ?? null;
81	  if (!tenantId) throw new Error(`create tenant ${created.status}: ${err(created)}`);
82	  const today = new Date().toLocaleDateString('en-CA', { timeZone: 'Asia/Manila' });
83	  const signed = await call('PATCH', `/api/platform/tenants/${tenantId}`, { cookie, json: { dpaSignedOn: today } });
84	  if (signed.status !== 200) throw new Error(`sign the DPA ${signed.status}: ${err(signed)}`);
85	  const on = await call('PUT', `/api/platform/tenants/${tenantId}/applications/bookings`, { cookie, json: { config: { timezone: 'Asia/Manila' } } });
86	  if (on.status !== 200) throw new Error(`bookings on ${on.status}: ${err(on)}`);
87	
88	  browser = await openBrowser({ scheme: 'light' });
89	  const { page } = browser;
90	  await page.send('Network.setCookie', { name: 'rag_platform', value: cookie.slice('rag_platform='.length), url: `${BASE}/api/platform/`, path: '/api/platform' });
91	
92	  /** /platform → this tenant → the Applications tab; the field scrolled to the middle. */
93	  async function openField(width) {
94	    await page.viewport(width);
95	    await page.goto(`${BASE}/platform`);
96	    if (!(await page.until(`[...document.querySelectorAll('.tenant-open')].some(b => b.textContent.trim() === ${JSON.stringify(NAME)})`, 30000))) throw new Error('the tenant is not listed');
97	    await page.eval(`[...document.querySelectorAll('.tenant-open')].find(b => b.textContent.trim() === ${JSON.stringify(NAME)}).click(); true`);
98	    if (!(await page.until("[...document.querySelectorAll('[role=tab]')].some(t => t.textContent.trim() === 'Applications')", 30000))) throw new Error('no Applications tab');
99	    await page.eval("[...document.querySelectorAll('[role=tab]')].find(t => t.textContent.trim() === 'Applications').click(); true");
100	    if (!(await page.until("!!document.querySelector('#bk-free') && document.querySelector('#bk-free').offsetParent !== null", 15000))) throw new Error('no #bk-free on screen');
101	    await page.eval("document.querySelector('#sec-limits').scrollIntoView({ block: 'start' }); window.scrollBy(0, -80); true");
102	    await sleep(300);
103	  }
104	  /** The viewport only: the Limits section with what is around it. */
105	  async function shot(name) {
106	    const r = await page.send('Page.captureScreenshot', { format: 'png' });
107	    writeFileSync(join(OUT, name), Buffer.from(r.result.data, 'base64'));
108	  }
109	  const field = () =>
110	    page.eval(
111	      "(() => { const i = document.querySelector('#bk-free'); const l = document.querySelector('label[for=bk-free]'); const h = i.closest('.field').querySelector('.hint'); const r = i.getBoundingClientRect(); return { label: l?.textContent, value: i.value, placeholder: i.placeholder, min: i.min, max: i.max, hint: h?.textContent.slice(0, 40), width: Math.round(r.width), right: Math.round(r.right), vw: innerWidth }; })()",
112	    );
113	  const toasts = () => page.eval("[...document.querySelectorAll('.toast')].map(t => (t.className.includes('error') ? 'error: ' : 'ok: ') + t.querySelector('.toast-message')?.textContent)");
114	  async function setValue(v) {
115	    await page.eval("document.querySelector('#bk-free').select(); true");
116	    await page.type('#bk-free', v);
117	  }
118	  const submit = () => page.eval("document.querySelector('#bk-free').form.requestSubmit(); true");
119	
120	  // 1
121	  await openField(1280);
122	  {
123	    const f = await field();
124	    await shot('platform-free-1280.png');
125	    check(f.label === 'Children stay free up to age' && f.value === '' && f.placeholder === 'none' && f.min === '0' && f.max === '17' && /3/.test(f.hint ?? ''),
126	      '1. 1280: the field in Limits, empty ("none"), 0–17, the hint under it (plan/free-guests/platform-free-1280.png)', JSON.stringify(f));
127	  }
128	
129	  // 2
130	  {
131	    await setValue('3');
132	    await submit();
133	    await page.until("[...document.querySelectorAll('.toast-message')].some(t => /saved/i.test(t.textContent))", 15000);
134	    const said = await toasts();
135	    const stored = await storedAge(tenantId);
136	    await openField(1280);
137	    const f = await field();
138	    await shot('platform-free-3-1280.png');
139	    check(said.some((t) => t === 'ok: Bookings config saved.') && stored === 3 && f.value === '3',
140	      '2. 3 and Save config: the toast says saved, the record holds 3, a fresh page shows 3 (platform-free-3-1280.png)', `toasts ${JSON.stringify(said)} · stored ${JSON.stringify(stored)} · shown ${JSON.stringify(f.value)}`);
141	  }
142	
143	  // 3
144	  {
145	    let sent = 0;
146	    page.on('Network.requestWillBeSent', (p) => { if (p.request.method === 'PUT' && p.request.url.includes('/applications/bookings')) sent++; });
147	    await setValue('18');
148	    const validity = await page.eval("(() => { const i = document.querySelector('#bk-free'); return { value: i.value, overflow: i.validity.rangeOverflow, message: i.validationMessage, invalid: i.matches(':invalid') }; })()");
149	    await page.eval("document.querySelector('#bk-free').form.reportValidity(); true");
150	    await submit();
151	    await sleep(1500);
152	    const sentNative = sent;
153	    await shot('platform-free-18-native-1280.png');
154	    // The server is still the guard: without the attribute, the form posts 18.
155	    await page.eval("document.querySelector('#bk-free').removeAttribute('max'); true");
156	    await submit();
157	    await page.until("[...document.querySelectorAll('.toast.error')].length > 0", 15000);
158	    const said = await toasts();
159	    await sleep(300);
160	    await shot('platform-free-18-refused-1280.png');
161	    const stored = await storedAge(tenantId);
162	    check(validity.overflow && validity.invalid && sentNative === 0 && sent === 1 && said.some((t) => /^error: .*free_up_to_age is a whole number of years from 0 to 17/.test(t)) && stored === 3,
163	      '3. 18: the native control refuses it and sends nothing; forced past it, the toast is the trigger\'s words; the record still 3 (platform-free-18-*-1280.png)',
164	      `validity ${JSON.stringify(validity)} · PUTs ${sentNative} then ${sent} · toasts ${JSON.stringify(said)} · stored ${JSON.stringify(stored)}`);
165	  }
166	
167	  // 4
168	  {
169	    await openField(375);
170	    const f = await field();
171	    await shot('platform-free-375.png');
172	    check(f.value === '3' && f.right <= f.vw && f.width > 0, '4. 375: the field shows 3 and fits the width (platform-free-375.png)', JSON.stringify(f));
173	  }
174	} catch (error) {
175	  check(false, 'setup', error.message);
176	} finally {
177	  browser?.close();
178	  if (tenantId) await supabase.from('tenants').delete().eq('id', tenantId);
179	  if (userId) {
180	    await supabase.from('audit_log').delete().eq('actor_user', userId);
181	    await supabase.from('platform_admins').delete().eq('user_id', userId);
182	    await supabase.auth.admin.deleteUser(userId);
183	  }
184	}
185	console.log(failures ? `\n${failures} FAILED` : '\nfree-guests platform walk: all passed');
186	process.exit(failures ? 1 : 0);
